import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import { ClientsPageClient } from './ClientsPageClient'

export const metadata: Metadata = {
  title: 'Clients — InkOS',
}

export default async function ClientsPage() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // S23 audit v1 — Clients page is the client list only. Tags moved to
  // /settings/tags, Consent Forms live in the sidebar, AI Design lives on
  // the individual client profile (or /ai-design).
  const [clientsResult, tagsResult] = await Promise.all([
    supabase
      .from('clients')
      .select('id, studio_id, first_name, last_name, email, phone, tags, total_spent_cents, total_sessions, last_visit_at, no_show_count, source, preferred_contact, archived_at, created_at, updated_at, date_of_birth, address, notes, referral_source, cancellation_count, loyalty_points, lifetime_value_cents, avg_session_value_cents, consent_minor, instagram_handle, tiktok_handle, website_url, is_banned, banned_reason, banned_at, banned_by, pronouns, avatar_url')
      .eq('studio_id', auth.studioId)
      .is('archived_at', null)
      .order('last_visit_at', { ascending: false, nullsFirst: false })
      .limit(50),
    supabase
      .from('client_tags')
      .select('id, name, color, icon')
      .eq('studio_id', auth.studioId)
      .order('name'),
  ])
  const initialClients = clientsResult.data ?? []
  const tagLibrary = tagsResult.data ?? []

  return (
    <PageShell>
      <PageHeader
        title="Clients"
        description="Manage client profiles, history, and notes."
      />

      <Suspense fallback={<div className="flex-1 animate-pulse bg-muted/20 m-6 rounded-xl" />}>
        <ClientsPageClient
          initialClients={initialClients}
          tagLibrary={tagLibrary}
        />
      </Suspense>
    </PageShell>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { PageHeader } from '@/components/shared/PageHeader'
import { PageTabs } from '@/components/shared/PageTabs'
import { filterTabsForRole } from '@/components/shared/page-tabs-utils'
import { Skeleton } from '@/components/ui/skeleton'
import { TransactionsTab } from '@/components/payments/tabs/TransactionsTab'
import { CommissionsTab } from '@/components/payments/tabs/CommissionsTab'
import { PayrollTab } from '@/components/payments/tabs/PayrollTab'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import type { PageTab } from '@/components/shared/PageTabs'
import { PageShell } from '@/components/shared/PageShell'

export const metadata: Metadata = {
  title: 'Payments — InkOS',
}

const VALID_TABS = ['transactions', 'commissions', 'payroll'] as const
type TabKey = (typeof VALID_TABS)[number]

interface SearchParams {
  tab?: string
}

function resolveTab(searchParams: SearchParams, role: NavRole): TabKey {
  const requested = searchParams.tab as TabKey | undefined
  if (requested && VALID_TABS.includes(requested)) {
    // Artists can only access commissions tab
    if (role === 'artist' && requested !== 'commissions') {
      return 'commissions'
    }
    return requested
  }
  // Default tab by role
  if (role === 'artist') return 'commissions'
  return 'transactions'
}

const PAYMENT_TABS: PageTab[] = [
  {
    key: 'transactions',
    label: 'Transactions',
    href: '/payments?tab=transactions',
    hidden: (role) => role === 'artist',
  },
  {
    key: 'commissions',
    label: 'Commissions',
    href: '/payments?tab=commissions',
    gated: 'studio',
    hidden: (role) => role === 'receptionist',
  },
  {
    key: 'payroll',
    label: 'Payroll',
    href: '/payments?tab=payroll',
    gated: 'pro',
    hidden: (role) => role === 'artist' || role === 'receptionist',
  },
]

const TabSkeleton = () => (
  <div className="p-6 space-y-4">
    <Skeleton className="h-8 w-32" />
    <Skeleton className="h-4 w-64" />
    <div className="space-y-2">
      {Array.from({ length: 8 }).map((_, i) => (
        <Skeleton key={i} className="h-12 w-full rounded-lg" />
      ))}
    </div>
  </div>
)

export default async function PaymentsPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>
}) {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { role, plan } = activeStudio
  const resolvedParams = await searchParams
  const activeTab = resolveTab(resolvedParams, role as NavRole)

  return (
    <PageShell>
      <PageHeader
        title="Payments"
        description="Transactions, commissions, and payroll in one place"
      />

      <div className="mt-6">
        <PageTabs
          tabs={filterTabsForRole(PAYMENT_TABS, role as NavRole)}
          activeKey={activeTab}
          currentPlan={plan as PlanTier}
          currentRole={role as NavRole}
          className="mb-0"
        />
      </div>

      <div className="flex-1 mt-0">
        {activeTab === 'transactions' && (
          <Suspense fallback={<TabSkeleton />}>
            <TransactionsTab />
          </Suspense>
        )}
        {activeTab === 'commissions' && (
          <Suspense fallback={<TabSkeleton />}>
            <CommissionsTab />
          </Suspense>
        )}
        {activeTab === 'payroll' && (
          <Suspense fallback={<TabSkeleton />}>
            <PayrollTab />
          </Suspense>
        )}
      </div>
    </PageShell>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { listProjects } from '@/lib/projects/queries'
import { ProjectsListClient } from '@/components/projects/ProjectsListClient'
import { Skeleton } from '@/components/ui/skeleton'
import type { ListProjectsFilters } from '@/lib/projects/queries'
import type { ProjectStatus } from '@/lib/projects/queries'

export const metadata: Metadata = {
  title: 'Projects — InkOS',
}

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function ProjectsPage({ searchParams }: Props) {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const params = await searchParams

  const getParam = (key: string) =>
    typeof params[key] === 'string' ? (params[key] as string) : undefined

  const filters: ListProjectsFilters = {}
  const statusParam = getParam('status')
  if (statusParam && ['active', 'completed', 'on_hold', 'cancelled'].includes(statusParam)) {
    filters.status = statusParam as ProjectStatus
  }
  const artistIdParam = getParam('artistId')
  if (artistIdParam) filters.artistId = artistIdParam
  const clientIdParam = getParam('clientId')
  if (clientIdParam) filters.clientId = clientIdParam
  const searchParam = getParam('search')
  if (searchParam) filters.search = searchParam

  const supabase = await createClient()

  const [projects, artistsResult] = await Promise.all([
    listProjects(auth.studioId, filters),
    supabase
      .from('artists')
      .select('id, display_name, avatar_url, sort_order')
      .eq('studio_id', auth.studioId)
      .eq('status', 'active')
      .order('sort_order'),
  ])

  const artists = artistsResult.data ?? []

  return (
    <Suspense
      fallback={
        <div className="p-6 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
          {Array.from({ length: 8 }).map((_, i) => (
            <Skeleton key={i} className="h-64 rounded-xl" />
          ))}
        </div>
      }
    >
      <ProjectsListClient
        initialProjects={projects}
        artists={artists}
        role={auth.role}
        initialFilters={filters}
      />
    </Suspense>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import {
  listConversations,
  getConversation,
  getConversationMessages,
  getClientBookingsSummary,
} from '@/lib/messaging/queries'
import { markConversationRead } from '@/lib/messaging/mutations'
import { MessagesShell } from '@/components/messages/MessagesShell'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'

export const metadata: Metadata = {
  title: 'Messages — InkOS',
}

export default async function MessagesPage() {
  let studioId: string

  try {
    const ctx = await getActiveStudio()
    studioId = ctx.studioId
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { conversations } = await listConversations(studioId, {
    limit: 50,
    archived: false,
  })

  // Auto-select the most recent conversation (desktop convenience;
  // mobile MessagesShell shows the list only and navigates on tap).
  const firstConversation = conversations[0] ?? null
  const activeConversationId = firstConversation?.id ?? null

  let activeConversation = null
  let activeMessages: Awaited<ReturnType<typeof getConversationMessages>> = []
  let recentBookings: Awaited<ReturnType<typeof getClientBookingsSummary>> = []

  if (activeConversationId) {
    activeConversation = await getConversation(studioId, activeConversationId)

    if (activeConversation) {
      const [msgs, bookings] = await Promise.all([
        getConversationMessages(studioId, activeConversationId, { limit: 50 }),
        activeConversation.client
          ? getClientBookingsSummary(studioId, activeConversation.client.id, 3)
          : Promise.resolve([]),
      ])
      activeMessages = msgs
      recentBookings = bookings

      if (activeConversation.unread_count > 0) {
        await markConversationRead(studioId, activeConversationId)
      }
    }
  }

  return (
    <PageShell fullHeight>
      <div className="px-4 py-4 sm:px-6 lg:px-8 shrink-0">
        <PageHeader
          title="Messages"
          description="SMS and email conversations with clients"
        />
      </div>
      <div className="flex-1 min-h-0">
        <MessagesShell
          conversations={conversations}
          activeConversation={activeConversation}
          activeMessages={activeMessages}
          recentBookings={recentBookings}
          studioId={studioId}
          activeConversationId={activeConversationId ?? undefined}
        />
      </div>
    </PageShell>
  )
}

/**
 * Messaging queries — server-side only (Server Components + Server Actions).
 *
 * All queries enforce studio_id scoping.
 * Uses the authenticated (anon key + session) client — RLS enforces access.
 */

import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import type { Conversation, ConversationChannel } from '@/lib/supabase/types'

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ClientSummary {
  id: string
  first_name: string
  last_name: string | null
  email: string | null
  phone: string | null
  avatar_url: string | null
  total_spent_cents: number
  total_sessions: number
}

export interface ConversationWithClient extends Conversation {
  client: ClientSummary | null
}

export interface ConversationMessage {
  id: string
  conversation_id: string | null
  channel: 'email' | 'sms' | 'whatsapp' | 'in_app'
  direction: 'outbound' | 'inbound'
  subject: string | null
  body: string
  status: 'queued' | 'sent' | 'delivered' | 'opened' | 'clicked' | 'failed' | 'bounced'
  sent_at: string | null
  delivered_at: string | null
  opened_at: string | null
  error: string | null
  provider_message_id: string | null
  metadata: Record<string, unknown>
  created_at: string
  updated_at: string
}

export interface ListConversationsFilters {
  channel?: ConversationChannel
  unreadOnly?: boolean
  assignedToMe?: boolean
  search?: string
  archived?: boolean
  limit?: number
  offset?: number
}

export interface ListConversationsResult {
  conversations: ConversationWithClient[]
  total: number
}

// ─── listConversations ────────────────────────────────────────────────────────

export async function listConversations(
  studioId: string,
  filters: ListConversationsFilters = {},
): Promise<ListConversationsResult> {
  const supabase = await createClient()
  const limit = filters.limit ?? 50
  const offset = filters.offset ?? 0

  let query = supabase
    .from('conversations')
    .select(
      `
      *,
      client:clients (
        id, first_name, last_name, email, phone,
        total_spent_cents, total_sessions
      )
    `,
      { count: 'exact' },
    )
    .eq('studio_id', studioId)
    .order('last_message_at', { ascending: false, nullsFirst: false })
    .range(offset, offset + limit - 1)

  // Archived / active filter
  if (filters.archived === true) {
    query = query.not('archived_at', 'is', null)
  } else {
    query = query.is('archived_at', null)
  }

  if (filters.channel) {
    query = query.eq('channel', filters.channel)
  }

  if (filters.unreadOnly) {
    query = query.gt('unread_count', 0)
  }

  if (filters.search) {
    // Search against display_name or external_identifier
    query = query.or(
      `display_name.ilike.%${filters.search}%,external_identifier.ilike.%${filters.search}%`,
    )
  }

  const { data, error, count } = await query

  if (error) {
    logger.error({ err: error, studioId }, 'messaging: listConversations failed')
    return { conversations: [], total: 0 }
  }

  return {
    conversations: (data ?? []) as ConversationWithClient[],
    total: count ?? 0,
  }
}

// ─── getConversation ──────────────────────────────────────────────────────────

export async function getConversation(
  studioId: string,
  conversationId: string,
): Promise<ConversationWithClient | null> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('conversations')
    .select(
      `
      *,
      client:clients (
        id, first_name, last_name, email, phone,
        total_spent_cents, total_sessions
      )
    `,
    )
    .eq('id', conversationId)
    .eq('studio_id', studioId)
    .single()

  if (error || !data) {
    if (error?.code !== 'PGRST116') {
      logger.error({ err: error, conversationId }, 'messaging: getConversation failed')
    }
    return null
  }

  return data as ConversationWithClient
}

// ─── getConversationMessages ──────────────────────────────────────────────────

export async function getConversationMessages(
  studioId: string,
  conversationId: string,
  opts: { limit?: number; before?: string } = {},
): Promise<ConversationMessage[]> {
  const supabase = await createClient()
  const limit = opts.limit ?? 50

  let query = supabase
    .from('client_communications')
    .select('id, conversation_id, channel, direction, subject, body, status, sent_at, delivered_at, opened_at, error, provider_message_id, metadata, created_at, updated_at')
    .eq('studio_id', studioId)
    .eq('conversation_id', conversationId)
    .order('created_at', { ascending: false })
    .limit(limit)

  if (opts.before) {
    query = query.lt('created_at', opts.before)
  }

  const { data, error } = await query

  if (error) {
    logger.error({ err: error, conversationId }, 'messaging: getConversationMessages failed')
    return []
  }

  // Return oldest-first for rendering (reverse the DESC query result)
  return ((data ?? []) as ConversationMessage[]).reverse()
}

// ─── searchMessages ───────────────────────────────────────────────────────────

export async function searchMessages(
  studioId: string,
  query: string,
): Promise<ConversationMessage[]> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('client_communications')
    .select('id, conversation_id, channel, direction, subject, body, status, sent_at, delivered_at, opened_at, error, provider_message_id, metadata, created_at, updated_at')
    .eq('studio_id', studioId)
    .or(`body.ilike.%${query}%,subject.ilike.%${query}%`)
    .order('created_at', { ascending: false })
    .limit(50)

  if (error) {
    logger.error({ err: error, studioId }, 'messaging: searchMessages failed')
    return []
  }

  return (data ?? []) as ConversationMessage[]
}

// ─── getUnreadConversationCount ───────────────────────────────────────────────

