/**
 * List all projects for a studio with joined client + artist + deposit balance.
 */
export async function listProjects(
  studioId: string,
  filters: ListProjectsFilters = {}
): Promise<ProjectListItem[]> {
  const supabase = await createClient()

  let query = supabase
    .from('projects')
    .select(`
      id, studio_id, client_id, primary_artist_id, name, description,
      placement, style, status, total_sessions_planned, total_price_cents,
      deposit_pool_cents, deposit_applied_cents, moodboard_url, cover_photo_url,
      started_at, completed_at, created_at, updated_at,
      client:clients!projects_client_id_fkey(id, first_name, last_name),
      primary_artist:artists!projects_primary_artist_id_fkey(id, display_name, avatar_url, sort_order)
    `)
    .eq('studio_id', studioId)
    .order('updated_at', { ascending: false })

  if (filters.status) {
    query = query.eq('status', filters.status)
  }
  if (filters.artistId) {
    query = query.eq('primary_artist_id', filters.artistId)
  }
  if (filters.clientId) {
    query = query.eq('client_id', filters.clientId)
  }
  if (filters.search) {
    query = query.ilike('name', `%${filters.search}%`)
  }

  const { data, error } = await query.limit(100)

  if (error) {
    logger.error(
      { error, studioId, code: error.code, message: error.message, hint: error.hint, details: error.details },
      'listProjects query failed — returning empty list',
    )
    return []
  }

  // Count completed sessions per project via separate query for each project
  const projectIds = (data ?? []).map((p) => p.id)
  let sessionCounts: Record<string, number> = {}

  if (projectIds.length > 0) {
    const { data: sessionsData } = await supabase
      .from('bookings')
      .select('project_id, status')
      .in('project_id', projectIds)
      .eq('status', 'completed')
      .eq('studio_id', studioId)

    for (const s of sessionsData ?? []) {
      if (!s.project_id) continue
      sessionCounts[s.project_id] = (sessionCounts[s.project_id] ?? 0) + 1
    }
  }

  return (data ?? []).map((p) => ({
    ...p,
    client: Array.isArray(p.client) ? (p.client[0] ?? null) : (p.client ?? null),
    primary_artist: Array.isArray(p.primary_artist) ? (p.primary_artist[0] ?? null) : (p.primary_artist ?? null),
    sessions_completed: sessionCounts[p.id] ?? 0,
    deposit_balance: Math.max(0, p.deposit_pool_cents - p.deposit_applied_cents),
  }))
}

