/**
 * Get project + client + artist + sessions for detail page.
 */
export async function getProjectWithSessions(
  studioId: string,
  id: string
): Promise<ProjectWithSessions | null> {
  const supabase = await createClient()

  const [projectResult, sessionsResult] = await Promise.all([
    supabase
      .from('projects')
      .select(`
        *,
        client:clients!projects_client_id_fkey(id, first_name, last_name, email, avatar_url),
        primary_artist:artists!projects_primary_artist_id_fkey(id, display_name, avatar_url, sort_order)
      `)
      .eq('id', id)
      .eq('studio_id', studioId)
      .single(),
    supabase
      .from('bookings')
      .select(`
        id, scheduled_at, session_number, status, price_cents,
        deposit_paid, deposit_cents,
        service:services!bookings_service_id_fkey(id, name, color),
        artist:artists!bookings_artist_id_fkey(id, display_name, avatar_url)
      `)
      .eq('project_id', id)
      .eq('studio_id', studioId)
      .order('session_number', { ascending: true, nullsFirst: false })
  ])

  if (projectResult.error) {
    if (projectResult.error.code === 'PGRST116') return null
    logger.error({ error: projectResult.error, id }, 'getProjectWithSessions failed')
    throw new Error('Failed to load project')
  }

  // Cast to Project row type to get all columns — the Supabase query infers
  // a partial type from the select string; casting gives us the full Row shape.
  const p = projectResult.data as unknown as Project & {
    client: { id: string; first_name: string; last_name: string | null; avatar_url: string | null; email: string | null } | Array<{ id: string; first_name: string; last_name: string | null; avatar_url: string | null; email: string | null }> | null
    primary_artist: { id: string; display_name: string; avatar_url: string | null; sort_order: number } | Array<{ id: string; display_name: string; avatar_url: string | null; sort_order: number }> | null
  }

  const sessions: ProjectSession[] = (sessionsResult.data ?? []).map((b) => ({
    id: b.id,
    scheduled_at: b.scheduled_at,
    session_number: b.session_number,
    status: b.status,
    price_cents: b.price_cents,
    deposit_paid: b.deposit_paid,
    deposit_cents: b.deposit_cents,
    service: Array.isArray(b.service) ? (b.service[0] ?? null) : (b.service ?? null),
    artist: Array.isArray(b.artist) ? (b.artist[0] ?? null) : (b.artist ?? null),
  }))

  return {
    ...p,
    client: Array.isArray(p.client) ? (p.client[0] ?? null) : (p.client ?? null),
    primary_artist: Array.isArray(p.primary_artist) ? (p.primary_artist[0] ?? null) : (p.primary_artist ?? null),
    sessions,
  }
}

