/**
 * Server-side helper to resolve the active location context for the current studio.
 *
 * Resolution order:
 *  1. Cookie `inkos_active_location` (httpOnly, SameSite=Lax, Max-Age 31536000)
 *  2. Studio's primary location (is_primary = true)
 *  3. First location ordered by sort_order ASC, created_at ASC
 *  4. null (all-locations view) — only returned if no locations exist
 *
 * "All locations" view (locationId = null) is only eligible for owner/admin roles.
 * Artists/receptionists/guest_artists always resolve to a specific location.
 */

import { cookies } from 'next/headers'
import { createClient } from '@/lib/supabase/server'
import type { Database } from '@/lib/supabase/types'
import type { StudioMemberRole } from '@/lib/context/active-studio'

export type LocationRow = Database['public']['Tables']['locations']['Row']

export interface ActiveLocationContext {
  /** null means "All locations" view — only for owner/admin */
  locationId: string | null
  location: LocationRow | null
  allLocations: LocationRow[]
}

const ALL_LOCATIONS_ROLES: StudioMemberRole[] = ['owner', 'admin']

export async function getActiveLocation(
  studioId: string,
  role: StudioMemberRole
): Promise<ActiveLocationContext> {
  const supabase = await createClient()

  // 1. Fetch all locations for this studio
  const { data: locations } = await supabase
    .from('locations')
    .select('*')
    .eq('studio_id', studioId)
    .order('sort_order', { ascending: true })
    .order('created_at', { ascending: true })

  const allLocations: LocationRow[] = locations ?? []

  if (allLocations.length === 0) {
    return { locationId: null, location: null, allLocations: [] }
  }

  // 2. Read cookie
  const cookieStore = await cookies()
  const cookieValue = cookieStore.get('inkos_active_location')?.value

  // Helper: check if role can use "All locations" view
  const canViewAll = ALL_LOCATIONS_ROLES.includes(role)

  // 3. Cookie value "null" means the user explicitly chose "All locations"
  if (cookieValue === 'null' && canViewAll) {
    return { locationId: null, location: null, allLocations }
  }

  if (cookieValue && cookieValue !== 'null') {
    // Validate location belongs to this studio
    const found = allLocations.find((l) => l.id === cookieValue)
    if (found) {
      return { locationId: found.id, location: found, allLocations }
    }
    // Cookie is stale (location deleted or studio switched) — fall through to default
  }

  // 4. Fallback: primary location first
  const primary = allLocations.find((l) => l.is_primary)
  const defaultLocation = primary ?? allLocations[0]

  if (!defaultLocation) {
    return { locationId: null, location: null, allLocations }
  }

  return {
    locationId: defaultLocation.id,
    location: defaultLocation,
    allLocations,
  }
}

import type { SupabaseClient } from '@supabase/supabase-js'
import type { Database } from '@/lib/supabase/types'

interface MtdOptions {
  artistId?: string
}

interface MtdSummary {
  totalCents: number
  count: number
}

/**
 * Returns the month-to-date approved/paid commission totals for a studio.
 * If artistId is provided, filters to that artist only.
 */
export async function getMtdCommissionTotal(
  supabase: SupabaseClient<Database>,
  studioId: string,
  opts?: MtdOptions,
): Promise<MtdSummary> {
  // date_trunc('month', NOW()) is not directly available via PostgREST filters,
  // so we compute the start of the current month in JS (same timezone as server UTC).
  const now = new Date()
  const monthStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1)).toISOString()

  let query = supabase
    .from('commission_records')
    .select('total_cents')
    .eq('studio_id', studioId)
    .in('status', ['approved', 'paid'])
    .gte('created_at', monthStart)

  if (opts?.artistId) {
    query = query.eq('artist_id', opts.artistId)
  }

  const { data, error } = await query

  if (error || !data) return { totalCents: 0, count: 0 }

  const totalCents = data.reduce((sum, row) => sum + (row.total_cents ?? 0), 0)
  return { totalCents, count: data.length }
}

import { cache } from 'react'
import { createClient } from '@/lib/supabase/server'
import type { Database } from '@/lib/supabase/types'

export type UserPinnedItem = Database['public']['Tables']['user_pinned_items']['Row']
export type PinnedItemKind = UserPinnedItem['kind']

/**
 * Fetch all pinned items for a user+studio pair.
 * Wrapped in React cache() so repeated calls within the same render tree
 * (layout + page) are deduplicated — one round-trip per request.
 */
export const fetchUserPins = cache(async (
  userId: string,
  studioId: string,
): Promise<UserPinnedItem[]> => {
  const supabase = await createClient()
  const { data, error } = await supabase
    .from('user_pinned_items')
    .select('*')
    .eq('user_id', userId)
    .eq('studio_id', studioId)
    .order('sort_order', { ascending: true })
    .limit(50)

  if (error) return []
  return data ?? []
})

/**
 * Check whether a specific item is pinned.
 * Delegates to fetchUserPins (also cached) — no extra query.
 */
export async function isPinned(
  userId: string,
  studioId: string,
  kind: PinnedItemKind,
  target: string,
): Promise<boolean> {
  const pins = await fetchUserPins(userId, studioId)
  return pins.some((p) => p.kind === kind && p.target === target)
}

