export type PresetRole = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'
export type CustomRole = `custom:${string}`
export type StudioRole = PresetRole | CustomRole

const PRESET_ROLE_LABELS: Record<PresetRole, string> = {
  owner:        'Owner',
  admin:        'Admin',
  artist:       'Artist',
  receptionist: 'Receptionist',
  guest_artist: 'Guest Artist',
}

function isPresetRole(role: string): role is PresetRole {
  return role in PRESET_ROLE_LABELS
}

/**
 * Fetches all granted permissions for the caller's role in the given studio.
 * Used server-side only — called once in (app)/layout.tsx.
 *
 * Returns a Set<string> of permission keys like 'bookings.create', 'payroll.view', etc.
 * Returns empty Set if the user has no studio membership (graceful fallback).
 *
 * Supports both preset roles and custom roles (custom:role_key pattern).
 */
export async function getUserPermissions(
  studioId: string,
  userId: string,
): Promise<Set<string>> {
  const supabase = await createClient()

  const { data: member } = await supabase
    .from('studio_members')
    .select('role')
    .eq('studio_id', studioId)
    .eq('user_id', userId)
    .is('deactivated_at', null)
    .single()

  if (!member) return new Set<string>()

  // Works for both preset and custom roles — role_permissions.role stores either
  const { data: perms } = await supabase
    .from('role_permissions')
    .select('permission_key')
    .eq('role', member.role)
    .eq('granted', true)

  return new Set<string>(perms?.map((p) => p.permission_key) ?? [])
}

/**
 * Returns the human-readable display name for a role.
 * For preset roles, returns the static label.
 * For custom roles, queries studio_custom_roles (cached within the React request).
 *
 * Falls back to the role key string if not found.
 */
export const getRoleDisplayName = cache(async (
  role: string,
  studioId: string,
): Promise<string> => {
  if (isPresetRole(role)) {
    return PRESET_ROLE_LABELS[role]
  }

  if (!role.startsWith('custom:')) return role

  const supabase = await createClient()
  const { data } = await supabase
    .from('studio_custom_roles')
    .select('display_name')
    .eq('role_key', role)
    .eq('studio_id', studioId)
    .single()

  return data?.display_name ?? role
})

/**
 * For nav filtering: maps a custom role back to its parent preset role.
 * This allows the nav to show the same items as the parent role.
 * Returns the role unchanged if it's already a preset or not found.
 */
export const resolveNavRole = cache(async (
  role: string,
  studioId: string,
): Promise<PresetRole> => {
  if (isPresetRole(role)) return role

  if (!role.startsWith('custom:')) return 'artist' // safe fallback

  const supabase = await createClient()
  const { data } = await supabase
    .from('studio_custom_roles')
    .select('cloned_from')
